corrected_code:
const express = require('express');
const NodeCache = require('node-cache');

const app = express();
const downloadLinkCache = new NodeCache({ stdTTL: 600 });

app.get('/api/exports/download-link/:jobId', (req, res) => {
  const { jobId } = req.params;

  // Retrieve cached export metadata
  const exportData = downloadLinkCache.get(jobId);
  if (!exportData || exportData.tenantId !== req.user.tenantId) {
    return res.status(404).json({ error: 'Export download link expired or not found' });
  }

  return res.json({
    jobId,
    downloadUrl: exportData.s3SignedUrl,
    fileSize: exportData.fileSizeBytes,
    completedAt: exportData.completedAt
  });
});

module.exports = app;
